def norm(text):
    """去掉空格与分隔符，《A · B》和《A·B》要算同一个来源。"""
    return re.sub(r"[\s·・\-—–/、]+", "", text or "")


def quote_ok(quote, labels_norm):
    q = norm(quote)
    if not q or quote.strip() in NON_KB_SOURCES:   # 《实时数据》是数据源说明，不算伪造引用
        return True
    return any(q in lb or lb.endswith(q) for lb in labels_norm)
